199	  public SummaryResponse calculateSummary(OrderRequest request) throws ValidationException, ServiceException {
200	    validateRequest(request);
201	
202	    List<PricingService.SummaryItem> items = new ArrayList<>();
203	    BigDecimal totalWeight = BigDecimal.ZERO;
204	
205	    for (OrderRequest.ItemRequest itemReq : request.items()) {
206	      Product product = productRepository.findById(itemReq.sku())
207	        .orElseThrow(() -> new ValidationException("UNKNOWN_PRODUCT"));
208	
209	      if (product.isDiscontinued()) {
210	        throw new ValidationException("PRODUCT_DISCONTINUED");
211	      }
212	
213	      items.add(new PricingService.SummaryItem(
214	        itemReq.sku(),
215	        itemReq.quantity(),
216	        product.getPrice()
217	      ));
218	
219	      totalWeight = totalWeight.add(
220	        product.getWeightKg().multiply(new BigDecimal(itemReq.quantity()))
221	      );
222	    }
223	
224	    ShippingMethod shippingMethod = parseShippingMethod(request.shippingMethod());
225	    Region region = parseRegion(request.region());
226	
227	    checkShippingAvailability(shippingMethod, totalWeight, request.zipCode());
228	
229	    BigDecimal shippingCost = BigDecimal.ZERO;
230	    int deliveryDays = 0;
231	
232	    if (shippingMethod == ShippingMethod.STORE_PICKUP) {
233	      deliveryDays = 1;
234	    } else if (shippingMethod == ShippingMethod.COURIER) {
235	      shippingCost = new BigDecimal("18.00");
236	      deliveryDays = 0;
237	    } else {
238	      try {
239	        String service = shippingMethod == ShippingMethod.ECONOMY ? "STD" : "EXP";
240	        TransLogClient.QuoteResponse quote = transLogClient.quote(
241	          request.zipCode(),
242	          totalWeight.intValue() * 1000,
243	          service
244	        );
245	        shippingCost = quote.price();
246	        deliveryDays = quote.etaDays() + region.getCarrierDaysAddition(shippingMethod);
247	      } catch (TransLogClient.ZipCodeNotServedException e) {
248	        throw new ValidationException("SHIPPING_METHOD_UNAVAILABLE");
249	      } catch (TransLogClient.TransLogUnavailableException e) {
250	        throw new ServiceException("CARRIER_UNAVAILABLE");
251	      } catch (Exception e) {
252	        throw new ServiceException("CARRIER_UNAVAILABLE");
253	      }
254	    }
255	
256	    ClubTier clubTier = parseClubTier(request.clubTier());
257	    PaymentMethod paymentMethod = parsePaymentMethod(request.paymentMethod());
258	    int installments = request.installments() != null ? request.installments() : 1;
259	
260	    validatePaymentMethod(paymentMethod, installments);
261	
262	    boolean isFirstPurchase = !orderRepository.hasCompletedOrders(request.customer().cpf());
263	
264	    BigDecimal productsSubtotal = calculateProductsSubtotal(items);
265	
266	    validateCoupon(request.coupon(), items, isFirstPurchase);
267	
268	    OrderSummary summary = pricingService.calculateSummary(
269	      items,
270	      request.coupon(),
271	      shippingMethod,
272	      shippingCost,
273	      deliveryDays,
274	      region,
275	      paymentMethod,
276	      installments,
277	      clubTier,
278	      isFirstPurchase
279	    );
280	
281	    if (paymentMethod == PaymentMethod.BANK_SLIP && summary.getFinalTotal().compareTo(new BigDecimal("1000.00")) > 0) {
282	      throw new ValidationException("PAYMENT_METHOD_UNAVAILABLE");
283	    }
284	
285	    return new SummaryResponse(
286	      summary.getProductsSubtotal(),
287	      summary.getCouponDiscount(),
288	      summary.getShippingCost(),
289	      summary.getDeliveryDays(),
290	      summary.getInsurance(),
291	      summary.getPaymentAdjustment(),
292	      summary.getFinalTotal(),
293	      summary.getInstallments(),
294	      summary.getInstallmentAmount(),
295	      summary.getNextPurchaseCredit(),
296	      summary.isGift()
297	    );
298	  }
