300	  @Transactional
301	  public OrderResponse createOrder(OrderRequest request) throws ValidationException, ServiceException {
302	    SummaryResponse summary = calculateSummary(request);
303	
304	    Order order = new Order(
305	      request.customer().cpf(),
306	      request.customer().email(),
307	      parseRegion(request.region()),
308	      parseShippingMethod(request.shippingMethod()),
309	      request.zipCode(),
310	      parsePaymentMethod(request.paymentMethod()),
311	      request.installments() != null ? request.installments() : 1,
312	      parseClubTier(request.clubTier()),
313	      request.coupon()
314	    );
315	
316	    for (OrderRequest.ItemRequest itemReq : request.items()) {
317	      Product product = productRepository.findById(itemReq.sku())
318	        .orElseThrow(() -> new ValidationException("UNKNOWN_PRODUCT"));
319	      order.addItem(itemReq.sku(), itemReq.quantity(), product.getPrice());
320	    }
321	
322	    OrderSummary summaryModel = new OrderSummary(
323	      summary.productsSubtotal(),
324	      summary.couponDiscount(),
325	      summary.shippingCost(),
326	      summary.deliveryDays(),
327	      summary.insurance(),
328	      summary.paymentAdjustment(),
329	      summary.finalTotal(),
330	      summary.installments(),
331	      summary.installmentAmount(),
332	      summary.nextPurchaseCredit(),
333	      summary.gift()
334	    );
335	
336	    order.setSummary(summaryModel);
337	    Order savedOrder = orderRepository.save(order);
338	
339	    return convertToResponse(savedOrder);
340	  }
