342	  @Transactional
343	  public OrderResponse processPayment(Long orderId, PaymentRequest paymentRequest) throws ValidationException, NotFoundException, OperationNotAllowedException {
344	    if (paymentRequest.transactionId() == null || paymentRequest.paidAt() == null) {
345	      throw new ValidationException("INVALID_ORDER");
346	    }
347	
348	    Order order = orderRepository.findByIdForUpdate(orderId)
349	      .orElseThrow(() -> new NotFoundException("ORDER_NOT_FOUND"));
350	
351	    if (order.getTransactionId() != null && order.getTransactionId().equals(paymentRequest.transactionId())) {
352	      return convertToResponse(order);
353	    }
354	
355	    if (!order.getStatus().equals(OrderStatus.AWAITING_PAYMENT)) {
356	      throw new OperationNotAllowedException("OPERATION_NOT_ALLOWED");
357	    }
358	
359	    if (order.isExpiredForPayment()) {
360	      order.cancel();
361	      orderRepository.save(order);
362	      createNotification(order.getCustomerCpf(), Notification.Type.ORDER_CANCELLED, orderId);
363	      throw new OperationNotAllowedException("ORDER_EXPIRED");
364	    }
365	
366	    checkStock(order);
367	
368	    order.markAsPaid(paymentRequest.transactionId(), paymentRequest.paidAt());
369	    decreaseStock(order);
370	
371	    Customer customer = customerRepository.findByCpfForUpdate(order.getCustomerCpf());
372	    if (customer == null) {
373	      customer = new Customer(order.getCustomerCpf(), order.getCustomerEmail());
374	    }
375	
376	    customer.addCredit(order.getSummary().getNextPurchaseCredit());
377	    customerRepository.save(customer);
378	
379	    Order savedOrder = orderRepository.save(order);
380	    createNotification(order.getCustomerCpf(), Notification.Type.PAYMENT_APPROVED, orderId);
381	
382	    return convertToResponse(savedOrder);
383	  }
