395	      throw new OperationNotAllowedException("OPERATION_NOT_ALLOWED");
396	    }
397	
398	    order.markAsShipped(shipmentRequest.trackingCode());
399	    Order savedOrder = orderRepository.save(order);
400	    createNotification(order.getCustomerCpf(), Notification.Type.ORDER_SHIPPED, orderId);
401	
402	    return convertToResponse(savedOrder);
403	  }
