420	  @Transactional
421	  public OrderResponse cancelOrder(Long orderId) throws NotFoundException, OperationNotAllowedException {
422	    Order order = orderRepository.findByIdForUpdate(orderId)
423	      .orElseThrow(() -> new NotFoundException("ORDER_NOT_FOUND"));
424	
425	    if (!order.canBeCancelled()) {
426	      throw new OperationNotAllowedException("OPERATION_NOT_ALLOWED");
427	    }
428	
429	    if (order.getStatus() == OrderStatus.PAID) {
430	      increaseStock(order);
431	      Customer customer = customerRepository.findByCpfForUpdate(order.getCustomerCpf());
432	      if (customer != null) {
433	        customer.removeCredit(order.getSummary().getNextPurchaseCredit());
434	        customerRepository.save(customer);
435	      }
436	    }
437	
438	    order.cancel();
439	    Order savedOrder = orderRepository.save(order);
440	    createNotification(order.getCustomerCpf(), Notification.Type.ORDER_CANCELLED, orderId);
441	
442	    return convertToResponse(savedOrder);
443	  }
