475	  private BigDecimal calculateProductsSubtotal(List<PricingService.SummaryItem> items) {
476	    return items.stream()
477	      .map(item -> item.price().multiply(new BigDecimal(item.quantity())))
478	      .reduce(BigDecimal.ZERO, BigDecimal::add);
479	  }
