481	  private void validateRequest(OrderRequest request) throws ValidationException {
482	    if (request.customer() == null || request.customer().cpf() == null || request.customer().email() == null) {
483	      throw new ValidationException("INVALID_ORDER");
484	    }
485	
486	    if (request.items() == null || request.items().isEmpty()) {
487	      throw new ValidationException("INVALID_ORDER");
488	    }
489	
490	    for (OrderRequest.ItemRequest item : request.items()) {
491	      if (item.sku() == null || item.quantity() == null || item.quantity() <= 0) {
492	        throw new ValidationException("INVALID_ORDER");
493	      }
494	    }
495	
496	    if (request.zipCode() == null || request.zipCode().isEmpty()) {
497	      throw new ValidationException("INVALID_ZIP_CODE");
498	    }
499	
500	    for (OrderRequest.ItemRequest itemReq : request.items()) {
501	      if (request.items().stream().filter(i -> i.sku().equals(itemReq.sku())).count() > 1) {
502	        throw new ValidationException("INVALID_ORDER");
503	      }
504	
505	      Product product = productRepository.findById(itemReq.sku()).orElse(null);
506	      if (product == null) {
507	        throw new ValidationException("UNKNOWN_PRODUCT");
508	      }
509	
510	      if (!product.hasEnoughStock(itemReq.quantity())) {
511	        throw new ValidationException("INSUFFICIENT_STOCK");
512	      }
513	    }
514	  }
515	
516	  private void validateCoupon(String coupon, List<PricingService.SummaryItem> items, boolean isFirstPurchase)
517	    throws ValidationException {
518	    if (coupon == null || coupon.isEmpty()) {
519	      return;
520	    }
521	
522	    Optional<Coupon> couponOpt = Coupon.fromCode(coupon);
523	    if (!couponOpt.isPresent()) {
524	      throw new ValidationException("INVALID_COUPON");
525	    }
526	
527	    Coupon couponEnum = couponOpt.get();
528	    BigDecimal subtotal = items.stream()
529	      .map(item -> item.price().multiply(new BigDecimal(item.quantity())))
530	      .reduce(BigDecimal.ZERO, BigDecimal::add);
531	
532	    List<Coupon.OrderItem> couponItems = items.stream()
533	      .map(item -> new Coupon.OrderItem(item.sku(), item.quantity(), item.price()))
534	      .toList();
535	
536	    Coupon.OrderContext ctx = new Coupon.OrderContext(
537	      couponItems,
538	      isFirstPurchase,
539	      ShippingMethod.STORE_PICKUP,
540	      BigDecimal.ZERO
541	    );
542	
543	    if (couponEnum.calculateDiscount(subtotal, ctx).isEmpty()) {
544	      throw new ValidationException("COUPON_NOT_APPLICABLE");
545	    }
546	  }
