562	  private void checkStock(Order order) throws OperationNotAllowedException {
563	    for (OrderItem item : order.getItems()) {
564	      Product product = productRepository.findById(item.getSku())
565	        .orElseThrow();
566	
567	      if (!product.hasEnoughStock(item.getQuantity())) {
568	        throw new OperationNotAllowedException("INSUFFICIENT_STOCK");
569	      }
570	    }
571	  }
