573	  private void decreaseStock(Order order) {
574	    for (OrderItem item : order.getItems()) {
575	      Product product = productRepository.findBySkuForUpdate(item.getSku());
576	      product.decreaseStock(item.getQuantity());
577	      productRepository.save(product);
578	    }
579	  }
