481	  private void validateRequest(OrderRequest request) throws ValidationException {
482	    if (request.customer() == null || request.customer().cpf() == null || request.customer().email() == null) {
483	      throw new ValidationException("INVALID_ORDER");
484	    }
485	
486	    if (request.items() == null || request.items().isEmpty()) {
487	      throw new ValidationException("INVALID_ORDER");
488	    }
489	
490	    for (OrderRequest.ItemRequest item : request.items()) {
491	      if (item.sku() == null || item.quantity() == null || item.quantity() <= 0) {
492	        throw new ValidationException("INVALID_ORDER");
493	      }
494	    }
495	
496	    if (request.zipCode() == null || request.zipCode().isEmpty()) {
497	      throw new ValidationException("INVALID_ZIP_CODE");
498	    }
499	
500	    for (OrderRequest.ItemRequest itemReq : request.items()) {
501	      if (request.items().stream().filter(i -> i.sku().equals(itemReq.sku())).count() > 1) {
502	        throw new ValidationException("INVALID_ORDER");
503	      }
504	
505	      Product product = productRepository.findById(itemReq.sku()).orElse(null);
506	      if (product == null) {
507	        throw new ValidationException("UNKNOWN_PRODUCT");
508	      }
509	
510	      if (!product.hasEnoughStock(itemReq.quantity())) {
511	        throw new ValidationException("INSUFFICIENT_STOCK");
512	      }
513	    }
514	  }
