516	  private void validateCoupon(String coupon, List<PricingService.SummaryItem> items, boolean isFirstPurchase)
517	    throws ValidationException {
518	    if (coupon == null || coupon.isEmpty()) {
519	      return;
520	    }
521	
522	    Optional<Coupon> couponOpt = Coupon.fromCode(coupon);
523	    if (!couponOpt.isPresent()) {
524	      throw new ValidationException("INVALID_COUPON");
525	    }
526	
527	    Coupon couponEnum = couponOpt.get();
528	    BigDecimal subtotal = items.stream()
529	      .map(item -> item.price().multiply(new BigDecimal(item.quantity())))
530	      .reduce(BigDecimal.ZERO, BigDecimal::add);
531	
532	    List<Coupon.OrderItem> couponItems = items.stream()
533	      .map(item -> new Coupon.OrderItem(item.sku(), item.quantity(), item.price()))
534	      .toList();
535	
536	    Coupon.OrderContext ctx = new Coupon.OrderContext(
537	      couponItems,
538	      isFirstPurchase,
539	      ShippingMethod.STORE_PICKUP,
540	      BigDecimal.ZERO
541	    );
542	
543	    if (couponEnum.calculateDiscount(subtotal, ctx).isEmpty()) {
544	      throw new ValidationException("COUPON_NOT_APPLICABLE");
545	    }
546	  }
